    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 a, uint256 w) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (a)); require(a <= 1000000000000000000000000000000);
        require(a > 0);
        require(w > 0);
        c.deposit{value: a}(); if (__ESBMC_reverted()) return;
        c.refund(); if (__ESBMC_reverted()) return;
        uint256 balBefore = address(c).balance;
        bool reverted;
        c.withdraw(w); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted && address(c).balance == balBefore);
    }
    receive() external payable {}
}

