// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 a, uint256 w) internal {
        a = bound(a, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(a > 0);
        vm.assume(w > 0);
        try c.deposit{value: a}() {} catch { return; }
        try c.refund() {} catch { return; }
        uint256 balBefore = address(c).balance;
        bool reverted;
        try c.withdraw(w) { reverted = false; }
        catch { reverted = true; }
        assertTrue(reverted && address(c).balance == balBefore);
    }

    function testFuzz_run(uint256 a, uint256 w) public {
        _run(a, w);
    }

    receive() external payable {}
}
